INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (1,'考研408','single','在带头结点的单链表中，删除 *p 结点的后继结点（设其后继存在）的正确操作序列是？','[{"key":"A","text":"q = p->next； p->next = q->next； free(q)；"},{"key":"B","text":"p->next = p->next->next； free(p->next)；"},{"key":"C","text":"free(p->next)； p->next = p->next->next；"},{"key":"D","text":"p->next = p->next->next； q = p->next； free(q)；"}]','A','必须先用 q 保存待删结点地址，再修改前驱的 next 指针，最后释放。B 先断链后 p->next 已指向新后继，free 掉的是本不该删的结点；C 先释放再访问属于非法访问；D 取到的是新后继，同样删错结点。',10,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (1,'考研408','single','长度为 n 的顺序表在第 i 个位置前插入元素，各合法插入位置等概率，则平均移动原有元素的个数为？','[{"key":"A","text":"n"},{"key":"B","text":"n/2"},{"key":"C","text":"(n+1)/2"},{"key":"D","text":"0"}]','B','在第 i 个位置前插入需要移动 n-i+1 个元素，i 从 1 到 n+1 等概率取值。移动次数总和为 n+(n-1)+…+0，除以 n+1 得 n/2。n 是表头插入的最坏情况，0 只对应表尾插入。',10,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (2,'考研408','single','设栈的入栈序列为 a、b、c、d、e，则下列哪个序列不可能是该栈的出栈序列？','[{"key":"A","text":"e d c b a"},{"key":"B","text":"d c e a b"},{"key":"C","text":"d e c b a"},{"key":"D","text":"a b c d e"}]','B','B 不可能：要 d 先出栈需先压入 a,b,c,d，弹出 d、c 后再压 e 弹 e，此时栈顶是 b 而非 a，只能得到 d c e b a。A 为全部压完再依次弹出；C、D 均可用合理的压弹时机实现。',10,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (2,'考研408','single','元素 1、2、3、4、5 依次入栈，允许入栈与出栈交替。下列哪个出栈序列不可能出现？','[{"key":"A","text":"2,1,4,3,5"},{"key":"B","text":"3,2,1,5,4"},{"key":"C","text":"3,1,2,5,4"},{"key":"D","text":"1,2,5,4,3"}]','C','若 3 首先出栈，则 1、2 已依次入栈且 2 位于 1 上方，所以 1 不可能先于 2 出栈。其余序列都能通过适当交替入栈和出栈得到，C 违反了栈的后进先出约束。',10,4);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (3,'考研408','single','循环队列存储在数组 A[0..m-1] 中，front 指向队头元素，rear 指向队尾元素的下一个位置，则队列中当前元素个数为？','[{"key":"A","text":"(rear - front + m) % m"},{"key":"B","text":"rear - front"},{"key":"C","text":"(rear - front + m) % m + 1"},{"key":"D","text":"(front - rear + m) % m"}]','A','循环队列下标是环形的，rear 可能小于 front，必须加 m 再取模得到环形距离。B 在 rear<front 时为负数；C 多加了 1，把队尾下一个位置也算进去了；D 方向反了。',10,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (3,'考研408','judge','循环队列为区分队空与队满，常牺牲一个存储单元，此时队满条件为 (rear + 1) % m == front。','[]','T','正确。牺牲一个单元后，队空为 rear == front，队满为 (rear+1)%m == front，两者不会混淆。代价是容量为 m 的数组最多只能存放 m-1 个元素。',10,2);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (3,'考研408','single','用两个容量足够的栈 S1、S2 模拟队列，入队只压入 S1。为保证出队正确，应在什么情况下把 S1 元素全部转入 S2？','[{"key":"A","text":"每次入队后"},{"key":"B","text":"S1 非空时始终转移"},{"key":"C","text":"仅当 S2 为空且需要出队时"},{"key":"D","text":"仅当 S1 已满时"}]','C','S2 非空时其栈顶就是当前队头，不能混入 S1 中较新的元素。仅当 S2 为空且需要出队时整体转移，元素次序经两次反转恢复先进先出，而且每个元素最多转移一次。',10,4);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (4,'考研408','single','已知一棵二叉树的中序遍历序列为 B D A E C F，后序遍历序列为 D B E F C A，则其先序遍历序列是？','[{"key":"A","text":"A B D C E F"},{"key":"B","text":"A B C D E F"},{"key":"C","text":"A D B C E F"},{"key":"D","text":"A B D E C F"}]','A','后序末位 A 为根；中序中 A 左侧 B D 为左子树、右侧 E C F 为右子树。左子树后序 D B 说明 B 为根且 D 为其右孩子；右子树后序 E F C 说明 C 为根，E、F 分别为左右孩子。先序即 A B D C E F。',10,4);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (4,'考研408','judge','已知一棵二叉树的先序遍历序列和中序遍历序列，可以唯一确定这棵二叉树。','[]','T','正确。先序首元素确定根，中序中根的位置划分出左右子树结点集合，再对两个子序列递归即可唯一重建。仅有先序+后序则一般不能唯一确定二叉树。',10,2);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (4,'考研408','single','一棵有 31 个结点的满二叉树删除编号 30 和 31 的两个叶结点后，剩余树中度为 1 的结点有几个？','[{"key":"A","text":"0"},{"key":"B","text":"1"},{"key":"C","text":"2"},{"key":"D","text":"15"}]','A','按完全二叉树层序编号，30 和 31 都是结点 15 的孩子。两者同时删除后，结点 15 由度为 2 变为叶结点，其他内部结点仍有两个孩子，因此没有度为 1 的结点。',10,4);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (5,'考研408','single','下列关于 B+ 树与 B 树的叙述中，正确的是？','[{"key":"A","text":"B+ 树中所有关键字都在叶子结点中出现，非叶结点只起索引作用"},{"key":"B","text":"B+ 树的叶子结点之间不能用指针相连"},{"key":"C","text":"B 树支持顺序查找，而 B+ 树不支持"},{"key":"D","text":"B+ 树的每个非叶结点也存放记录的物理地址"}]','A','B+ 树的全部关键字都出现在叶子层，非叶结点只是索引（分界关键字），且叶子用链表串联，因此既支持随机查找又支持顺序扫描。B 错，叶子正是靠指针串联；C 恰好说反；D 错，只有叶子层才带记录指针。',10,4);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (6,'考研408','single','对关键字序列 {49, 38, 65, 97, 76, 13, 27} 进行一趟快速排序，以首元素 49 为枢轴并采用两端交替扫描、枢轴暂存（挖坑法）的划分方式，划分结束时序列为？','[{"key":"A","text":"27 38 13 49 76 97 65"},{"key":"B","text":"13 27 38 49 65 76 97"},{"key":"C","text":"27 38 13 49 65 76 97"},{"key":"D","text":"38 13 27 49 76 97 65"}]','A','一趟划分后枢轴 49 归位到第 4 位，左侧 27、38、13 均小于它，右侧 76、97、65 均大于它，但两侧内部仍无序。B 是排序全部结束后的有序序列，不是一趟划分的结果。',10,4);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (6,'考研408','judge','快速排序是不稳定排序，且其平均时间复杂度为 O(n log₂ n)。','[]','T','正确。划分过程中的远距离交换会改变相同关键字的相对次序，故不稳定；平均情况下每层划分共 O(n)、递归深度 O(log n)，因此平均 O(n log n)，最坏为 O(n²)。',10,2);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (6,'考研408','single','快速排序每次选择当前子表首元素为枢轴。对哪种初始序列排序时，递归树最不平衡？','[{"key":"A","text":"完全随机序列"},{"key":"B","text":"严格递增序列"},{"key":"C","text":"首尾交错序列"},{"key":"D","text":"元素均匀分散序列"}]','B','严格递增时首元素总是当前最小值，每次划分得到规模 0 与 n-1 的两个子表，递归深度达到 n，时间退化为 O(n²)。其他序列通常不会持续产生这种极端划分。',10,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (7,'考研408','single','对长度为 n 的序列进行二路归并排序，其时间复杂度和辅助空间复杂度分别是？','[{"key":"A","text":"O(n log n) 与 O(n)"},{"key":"B","text":"O(n log n) 与 O(1)"},{"key":"C","text":"O(n²) 与 O(n)"},{"key":"D","text":"O(n log n) 与 O(n log n)"}]','A','二路归并需要 n 个元素的暂存数组，故辅助空间 O(n)；递归共 log n 层，每层归并扫描 n 个元素，时间 O(n log n)。它不像堆排序那样可以原地完成，这是其主要代价。',10,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (7,'考研408','single','对 16 个记录做自底向上的二路归并排序，从长度为 1 的有序段开始，完成排序需要多少趟归并？','[{"key":"A","text":"3"},{"key":"B","text":"4"},{"key":"C","text":"8"},{"key":"D","text":"15"}]','B','每趟归并使有序段长度翻倍，依次由 1 变为 2、4、8、16，因此需要 log₂16=4 趟。15 是归并树内部结点数量，不是扫描全体记录的归并趟数，8 也只对应局部合并次数。',10,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (8,'考研408','single','无向图 G 的边集为 {(1,2), (1,3), (2,4), (2,5), (3,6)}。从顶点 1 出发进行广度优先遍历，下列哪个序列不可能出现？','[{"key":"A","text":"1 2 3 4 5 6"},{"key":"B","text":"1 3 2 6 4 5"},{"key":"C","text":"1 2 3 5 4 6"},{"key":"D","text":"1 2 4 3 5 6"}]','D','BFS 借助队列按层次展开：1 的邻接点 2、3 必须先出队，它们派生的 4、5、6 才可能被访问。D 中 4 排在 3 之前，违背先进先出规则。A、B、C 均可通过调整邻接表顺序得到。',10,5);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (8,'考研408','judge','对同一个无向连通图，从同一顶点出发进行深度优先遍历，得到的遍历序列是唯一的。','[]','F','错误。DFS 结果取决于邻接表中顶点的排列顺序，同一图从同一顶点出发可得到多个不同的 DFS 序列。只有各顶点邻接点顺序固定时才唯一。',10,2);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (8,'考研408','single','无向连通图有 8 个顶点和 12 条边，采用邻接表存储并执行一次完整 BFS，其时间复杂度为？','[{"key":"A","text":"O(8)"},{"key":"B","text":"O(12)"},{"key":"C","text":"O(8+12)"},{"key":"D","text":"O(8×12)"}]','C','BFS 中每个顶点至多入队、出队一次，邻接表中的每条边端点记录也只扫描常数次，因此复杂度为 O(V+E)，本题即 O(8+12)。只写顶点数或边数都会漏掉另一部分工作。',10,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (9,'考研408','single','TCP 建立连接时，客户发送的 SYN 报文段序号 seq = x，则服务器回送的 SYN+ACK 报文段以及客户最后发送的 ACK 报文段的序号与确认号分别是？','[{"key":"A","text":"服务器 seq = y、ack = x+1；客户 seq = x+1、ack = y+1"},{"key":"B","text":"服务器 seq = y、ack = x；客户 seq = x+1、ack = y"},{"key":"C","text":"服务器 seq = x+1、ack = y+1；客户 seq = y、ack = x+1"},{"key":"D","text":"服务器 seq = y+1、ack = x+1；客户 seq = x+1、ack = y+1"}]','A','第二报文由服务器发出，序号取服务器初始序号 y，确认号为客户序号加 1；第三报文序号为 x+1（SYN 消耗一个序号），确认号为 y+1。ACK 报文若不携带数据则不消耗序号。',10,4);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (9,'考研408','single','TCP 客户端发送 SYN，序号为 100，服务器回复 SYN+ACK，序号为 300。第三次握手的序号与确认号分别为？','[{"key":"A","text":"100 和 300"},{"key":"B","text":"101 和 301"},{"key":"C","text":"101 和 300"},{"key":"D","text":"100 和 301"}]','B','SYN 虽不携带应用数据，但会占用一个序号。客户端下一序号为 101，服务器 SYN 之后期望的确认号为 301，所以第三次握手使用 seq=101、ack=301，其他选项至少漏加一方的 SYN 序号。',10,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (10,'考研408','single','TCP 释放连接时，主动关闭方发出 FIN 报文段后进入的状态是？','[{"key":"A","text":"FIN_WAIT_1"},{"key":"B","text":"FIN_WAIT_2"},{"key":"C","text":"CLOSE_WAIT"},{"key":"D","text":"LAST_ACK"}]','A','发送 FIN 后进入 FIN_WAIT_1；收到对方 ACK 后转为 FIN_WAIT_2；收到对方的 FIN 并发出最后 ACK 后进入 TIME_WAIT。CLOSE_WAIT 和 LAST_ACK 属于被动关闭方的状态。',10,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (10,'考研408','single','TCP 主动关闭方收到对端 FIN 并回复最后一个 ACK 后，通常要等待 2MSL，主要目的之一是？','[{"key":"A","text":"提高拥塞窗口"},{"key":"B","text":"允许最后 ACK 丢失后再次确认重传的 FIN"},{"key":"C","text":"重新协商端口号"},{"key":"D","text":"避免校验报文"}]','B','若最后 ACK 丢失，对端会重传 FIN，主动关闭方在 TIME-WAIT 中仍可再次发送 ACK。同时等待也能让旧连接报文在网络中消失。其余选项与可靠释放连接无关。',10,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (11,'考研408','single','某路由器转发表中有 4 条表项：① 202.118.128.0/17 ② 202.118.130.0/23 ③ 0.0.0.0/0 ④ 202.118.132.0/22。目的地址 202.118.130.1 将按哪条表项转发？','[{"key":"A","text":"①"},{"key":"B","text":"②"},{"key":"C","text":"③"},{"key":"D","text":"④"}]','B','目的地址同时匹配 /17 与 /23，但最长前缀匹配应选择更具体的 /23 表项。/22 表项覆盖 132.0 至 135.255，不含该地址，默认路由只在没有具体路由匹配时使用。',10,4);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (11,'考研408','judge','IP 数据报首部中的片偏移字段以 8 字节为单位计量。','[]','T','正确。因片偏移字段只有 13 位，无法以字节为单位表示最大 65535 的偏移，故规定单位为 8 字节；除最后一片外，各分片的数据部分长度必须是 8 字节的整数倍。',10,2);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (11,'考研408','single','某主机 IPv4 地址为 192.168.10.130/26，该主机所在子网的广播地址是？','[{"key":"A","text":"192.168.10.127"},{"key":"B","text":"192.168.10.191"},{"key":"C","text":"192.168.10.255"},{"key":"D","text":"192.168.10.129"}]','B','/26 每个子网包含 64 个地址，网段边界为 0、64、128、192。地址 130 位于 128 至 191 的子网，网络地址为 128，广播地址为 191。127 属于前一子网，255 是整个 /24 的广播地址。',10,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (12,'考研408','judge','ARP 请求报文以广播方式发送，而 ARP 响应报文以单播方式发回请求者。','[]','T','正确。请求时只知道目标 IP 不知其 MAC，只能广播；目标主机收到后在响应报文中填入自己的 MAC，并以单播直接回送请求者，从而避免不必要的广播开销。',10,2);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (13,'考研408','single','某 TCP 连接中拥塞窗口 cwnd 初值为 1 MSS，慢开始门限 ssthresh 初值为 8 MSS。当 cwnd 增至 8 后转入拥塞避免，在 cwnd = 12 MSS 时收到 3 个重复确认，则执行快恢复后新的 ssthresh 与 cwnd 分别是？','[{"key":"A","text":"6 MSS 与 6 MSS"},{"key":"B","text":"6 MSS 与 1 MSS"},{"key":"C","text":"12 MSS 与 6 MSS"},{"key":"D","text":"1 MSS 与 6 MSS"}]','A','收到 3 个重复确认属快重传情形：新 ssthresh = cwnd/2 = 6，并令 cwnd = 新门限 6 后直接转入拥塞避免（快恢复），不回退到慢开始。只有超时重传才会把 cwnd 重置为 1 并门限减半。',10,4);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (13,'考研408','single','TCP 慢开始阶段当前拥塞窗口为 8 MSS，本轮报文均被独立确认。下一轮开始时拥塞窗口通常约为？','[{"key":"A","text":"9 MSS"},{"key":"B","text":"12 MSS"},{"key":"C","text":"16 MSS"},{"key":"D","text":"64 MSS"}]','C','慢开始中每收到一个新确认，拥塞窗口约增加 1 MSS，一个往返时间内确认当前窗口的数据后，窗口近似翻倍，由 8 MSS 增至 16 MSS。线性增加约 1 MSS 是拥塞避免阶段的特征。',10,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (14,'考研408','single','运行中的进程提出 I/O 请求后，其状态将发生何种转换？','[{"key":"A","text":"运行态 → 阻塞态"},{"key":"B","text":"运行态 → 就绪态"},{"key":"C","text":"阻塞态 → 运行态"},{"key":"D","text":"就绪态 → 阻塞态"}]','A','进程主动请求尚未就绪的资源（如等待 I/O 完成）时会被阻塞，让出 CPU；只有时间片到或被更高优先级进程抢占才是运行 → 就绪。阻塞态进程只能被唤醒为就绪态，不能直接回到运行态。',10,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (14,'考研408','judge','进程控制块 PCB 是进程存在的唯一标志，操作系统通过 PCB 感知和管理进程。','[]','T','正确。PCB 中保存进程标识、状态、现场信息、资源清单与调度参数，进程创建即建立 PCB、撤销即回收 PCB，系统的一切进程管理操作都以 PCB 为依据。',10,2);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (15,'考研408','single','有 4 个作业 J1、J2、J3、J4，同时到达（到达时间均为 0），运行时间分别为 8、4、9、5。采用非抢占的短作业优先（SJF）调度，其平均周转时间是？','[{"key":"A","text":"14"},{"key":"B","text":"16.75"},{"key":"C","text":"26.5"},{"key":"D","text":"12"}]','A','调度次序为 J2(4)、J4(5)、J1(8)、J3(9)，完成时刻分别为 4、9、17、26，因到达时间为 0，周转时间即为完成时刻，平均值 = (4+9+17+26)/4 = 14。16.75 是先来先服务的结果。',10,4);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (15,'考研408','single','进程 P1、P2 在时刻 0 同时到达，运行时间分别为 5 和 3，时间片为 2，按 P1、P2 顺序进入队列。P2 完成时刻为？','[{"key":"A","text":"5"},{"key":"B","text":"6"},{"key":"C","text":"7"},{"key":"D","text":"8"}]','C','执行顺序为 P1 两单位、P2 两单位、P1 两单位、P2 一单位，所以 P2 在时刻 7 完成，之后 P1 再运行最后一单位。选项 5 忽略等待，6 少算一次轮转，8 是全部进程完成时刻。',10,4);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (16,'考研408','single','系统为某进程分配 3 个物理块（初始为空），页面访问序列为 4 3 2 1 4 3 5 4 3 2 1 5。采用 LRU 置换算法，产生的缺页次数是？','[{"key":"A","text":"9 次"},{"key":"B","text":"10 次"},{"key":"C","text":"11 次"},{"key":"D","text":"8 次"}]','B','逐次跟踪最近使用时间：前 7 次访问全部缺页，第 8、9 次访问 4、3 命中，第 10~12 次访问 2、1、5 又都缺页，共 12 - 2 = 10 次。同序列下 FIFO 为 9 次，说明 LRU 并非在所有序列上都优于 FIFO。',10,5);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (16,'考研408','single','某进程有 3 个页框，访问序列为 1,2,3,1,4,2,5，采用 LRU 且初始为空，共发生多少次缺页？','[{"key":"A","text":"4"},{"key":"B","text":"5"},{"key":"C","text":"6"},{"key":"D","text":"7"}]','C','访问 1、2、3 各缺页，随后访问 1 命中。访问 4 淘汰最久未用的 2，接着访问 2 又缺页并淘汰 3，访问 5 再缺页，因此共 6 次。只统计不同页面会漏掉 2 的再次缺页。',10,4);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (17,'考研408','single','系统中有 3 个并发进程，每个进程都需要 4 台同类的打印机资源，则系统至少配备多少台打印机时，无论怎样分配都不会发生死锁？','[{"key":"A","text":"9 台"},{"key":"B","text":"10 台"},{"key":"C","text":"11 台"},{"key":"D","text":"12 台"}]','B','最坏情况是每个进程都已获得 3 台（共 9 台）并都在等待第 4 台，此时形成死锁；只要再增加 1 台（共 10 台），必有某进程能获得全部 4 台运行完毕后释放资源，从而打破循环等待。',10,4);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (17,'考研408','single','系统有 3 个同类资源，P1 已占 1 个还需 1 个，P2 已占 1 个还需 2 个，当前剩余 1 个。下列判断正确的是？','[{"key":"A","text":"存在安全序列 P1、P2"},{"key":"B","text":"存在安全序列 P2、P1"},{"key":"C","text":"两个序列都安全"},{"key":"D","text":"当前必然死锁"}]','A','先把剩余资源给 P1，P1 可完成并释放所占的 2 个资源，此时可用数增至 2，足以满足 P2 的剩余需求，所以 P1、P2 是安全序列。P2 当前不能先完成，但系统并未死锁。',10,4);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (18,'考研408','single','某五段流水线（取指、译码、执行、访存、写回）各段耗时分别为 2 ns、1 ns、3 ns、2 ns、1 ns，段间寄存器建立时间为 1 ns，则流水线的时钟周期至少应取？','[{"key":"A","text":"3 ns"},{"key":"B","text":"4 ns"},{"key":"C","text":"5 ns"},{"key":"D","text":"9 ns"}]','B','时钟周期必须容纳最慢的段并留出寄存器锁存时间，故取 max(各段耗时) + 寄存器延时 = 3 + 1 = 4 ns。只取 3 ns 会导致执行段来不及完成，取 9 ns 则把各段之和误当成周期。',10,4);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (19,'考研408','single','某计算机 Cache 存取时间为 5 ns，主存存取时间为 50 ns，Cache 命中率为 95%，则该存储系统的平均访问时间约为？','[{"key":"A","text":"7.5 ns"},{"key":"B","text":"25 ns"},{"key":"C","text":"47.5 ns"},{"key":"D","text":"9.75 ns"}]','A','每次先访问 Cache，命中耗时 5 ns，未命中还需增加 50 ns 主存时间，因此平均时间为 0.95×5+0.05×55=7.5 ns。其余选项或漏算 Cache 开销，或错误使用命中率。',10,4);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (20,'考研408','single','用 8 位补码做 87 与 45 的减法运算，结果的补码以及溢出标志 OF 分别是？','[{"key":"A","text":"00101010，OF = 0"},{"key":"B","text":"00101010，OF = 1"},{"key":"C","text":"11010011，OF = 0"},{"key":"D","text":"10101010，OF = 1"}]','A','87 的补码为 01010111，-45 的补码为 11010011，相加保留低 8 位得 00101010，即十进制 42。正数减正数的结果在表示范围内，所以 OF 为 0，最高进位不能等同于有符号溢出。',10,4);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (20,'考研408','single','8 位补码运算中，01111111 与 00000001 相加的结果和溢出情况是？','[{"key":"A","text":"10000000，无溢出"},{"key":"B","text":"10000000，有溢出"},{"key":"C","text":"00000000，有溢出"},{"key":"D","text":"01111110，无溢出"}]','B','01111111 表示 127，加 1 的低 8 位结果为 10000000，按补码解释为 -128。两个正数相加却得到负数，符号异常，说明发生有符号溢出，但机器仍保留该低 8 位结果。',10,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (32,'考研408','single','带权连通无向图的顶点为 1~5，边及权值为：1-2(3)、1-3(1)、2-3(2)、2-4(5)、3-4(4)、3-5(6)、4-5(2)。该图的最小生成树权值是？','[{"key":"A","text":"9"},{"key":"B","text":"10"},{"key":"C","text":"11"},{"key":"D","text":"8"}]','A','按 Kruskal 排序取边：1-3(1)、2-3(2)、4-5(2) 入选；1-2(3) 两端已连通故舍去；3-4(4) 连接两个连通分量入选。共 4 条边，权值 1+2+2+4 = 9。',10,4);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (33,'考研408','single','设哈希函数 H(key) = key mod 11，用线性探测法处理冲突，依次插入关键字 {22, 41, 53, 46, 30, 19}，则关键字 30 最终的存储地址是？','[{"key":"A","text":"8"},{"key":"B","text":"9"},{"key":"C","text":"10"},{"key":"D","text":"0"}]','C','22→0，41→8，53→9，46→2；30 mod 11 = 8 与 41 冲突，向后探测 9 被 53 占用，再探测 10 为空，落在地址 10。注意线性探测是顺序后移（可回绕），不是二次探测。',10,4);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (34,'考研408','single','某 Cache 容量为 16 KB，块大小为 32 B，采用 4 路组相联映射，主存地址 32 位。则主存地址中组号（index）字段的位数是？','[{"key":"A","text":"7 位"},{"key":"B","text":"8 位"},{"key":"C","text":"9 位"},{"key":"D","text":"6 位"}]','A','Cache 共 16 KB÷32 B=512 行，四路组相联得到 128 组，即 2 的 7 次方组，所以组号占 7 位。块内偏移占 5 位，不能把 512 行对应的 9 位误作组号位数。',10,4);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (34,'考研408','single','32 位字节地址的直接映射 Cache 容量为 16 KB，块大小为 64 B，地址中的行号字段占多少位？','[{"key":"A","text":"6"},{"key":"B","text":"8"},{"key":"C","text":"10"},{"key":"D","text":"14"}]','B','Cache 行数为 16 KB÷64 B=256，即 2 的 8 次方，因此行号字段占 8 位。块内偏移由 64 B 决定，占 6 位，不能把偏移位数或总容量指数误作行号位数。',10,4);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (1,'软考','judge','单链表不具有随机访问特性，查找第 i 个结点必须从表头沿指针顺序扫描，时间复杂度为 O(n)。','[]','T','正确。单链表的存储地址不连续，也没有下标映射，只能通过 next 指针逐个后移，平均比较 n/2 次，故按位查找为 O(n)，这也是它相对于顺序表的主要劣势。',5,1);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (1,'软考','single','单链表中已定位到待删除结点的前驱，完成删除操作的时间复杂度是？','[{"key":"A","text":"O(1)"},{"key":"B","text":"O(log n)"},{"key":"C","text":"O(n)"},{"key":"D","text":"O(n log n)"}]','A','已知前驱后，只需让前驱指针越过待删结点并释放该结点，操作次数与链表长度无关，因此为 O(1)。若只知道关键字而必须从表头查找，整体复杂度才会变为 O(n)。',5,2);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (2,'软考','single','利用栈将中缀表达式 a + b * c - d 转换为后缀表达式，结果是？','[{"key":"A","text":"a b c * + d -"},{"key":"B","text":"a b c + * d -"},{"key":"C","text":"a b + c * d -"},{"key":"D","text":"a b c * - d +"}]','A','运算符栈按优先级出栈：读到 + 入栈，读到 * 优先级更高入栈；读到 - 时依次弹出 *、+，再压入 -；最后弹出 -。故为 abc*+d-。B 错在让 + 先于 * 出栈，颠倒了乘除优先于加减的规则。',5,2);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (2,'软考','single','编译器把中缀表达式 a+b×c-d 转换为后缀表达式，正确结果是？','[{"key":"A","text":"ab+c×d-"},{"key":"B","text":"abc×+d-"},{"key":"C","text":"abc+×d-"},{"key":"D","text":"ab+c×-d"}]','B','乘法优先于加减，因此先形成 b c ×，再与 a 做加法，最后减去 d，后缀序列为 a b c × + d -。A 先执行了加法，C 改变乘法操作数，D 不符合后缀表达式结构。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (3,'软考','single','循环队列数组长度为 8，front 指向队头，rear 指向下一个可插入位置，并牺牲一个单元。最多可保存多少个元素？','[{"key":"A","text":"6"},{"key":"B","text":"7"},{"key":"C","text":"8"},{"key":"D","text":"9"}]','B','为用 front=rear 表示队空，需要保留一个数组单元，使队满条件为 (rear+1) mod 8=front，因此最多保存 8-1=7 个元素。选择 8 忽略了区分队空与队满所牺牲的单元。',5,2);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (4,'软考','single','一棵含有 n 个结点的完全二叉树，其叶子结点个数为？','[{"key":"A","text":"⌊n/2⌋"},{"key":"B","text":"⌈n/2⌉"},{"key":"C","text":"⌊log2 n⌋ + 1"},{"key":"D","text":"n - 1"}]','B','完全二叉树中度为 1 的结点最多 1 个，由 n = n0 + n1 + n2 与 n0 = n2 + 1 可得 n0 = ⌈n/2⌉。例如 n=5 时叶子为 3、n=6 时叶子为 3，均符合该公式；A 会少算一个。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (4,'软考','single','组合模式把对象组织为树结构，若业务要求先处理组合根，再依次处理各子对象，最接近哪种遍历？','[{"key":"A","text":"先序遍历"},{"key":"B","text":"中序遍历"},{"key":"C","text":"只访问叶结点"},{"key":"D","text":"逆序冒泡"}]','A','先处理根对象，再递归访问各个子组合或叶子，正是树的先序遍历思想，也符合组合模式从整体向局部执行操作的常见方式。中序主要针对二叉树，逆序冒泡与树结构无关。',5,2);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (5,'软考','single','在 B+ 树中插入关键字时，若某结点关键字数超过上限且其左右兄弟结点均已满，则采取的处理方式是？','[{"key":"A","text":"该结点一分为二，中间关键字提升到父结点"},{"key":"B","text":"直接丢弃超出的关键字"},{"key":"C","text":"重建整棵 B+ 树"},{"key":"D","text":"把多余的结点直接挂到根结点下"}]','A','兄弟已满无法调剂，只能分裂：结点分成两个，中间关键字上移到父结点（B+ 树中该关键字在叶子层仍保留副本）。B 会丢失数据；C 代价过大；D 破坏平衡结构。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (5,'软考','single','数据库 B+ 树索引执行范围查询，定位到范围下界所在叶结点后，主要依靠什么继续读取？','[{"key":"A","text":"叶结点间的有序链指针"},{"key":"B","text":"根结点的父指针"},{"key":"C","text":"随机扫描内部结点"},{"key":"D","text":"哈希桶冲突链"}]','A','B+ 树的数据项集中在叶结点，叶结点按关键字有序链接。定位下界后沿叶链扫描到超过上界即可，无需反复回到根结点。其他结构不能提供连续、高效的范围读取。',5,2);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (6,'软考','single','快速排序在下列哪种情况下时间复杂度最差？','[{"key":"A","text":"初始序列随机无序"},{"key":"B","text":"初始序列已基本有序，且总取第一个元素作为枢轴"},{"key":"C","text":"枢轴每次都恰好取到中位数"},{"key":"D","text":"每趟划分后两个子区间长度基本相等"}]','B','基本有序时取首元素为枢轴会使划分极度不平衡（一侧为空），退化为 O(n²)。C、D 对应最好的划分，复杂度 O(n log n)；A 为平均情况，期望也是 O(n log n)。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (7,'软考','single','归并两个有序序列时，若关键字相等总是先取左序列元素，该实现具有什么性质？','[{"key":"A","text":"保持排序稳定性"},{"key":"B","text":"把时间复杂度降为 O(n)"},{"key":"C","text":"不再需要辅助空间"},{"key":"D","text":"必然改为降序"}]','A','相等关键字分处左右子序列时，先取左侧元素会保留它们在原序列中的先后关系，各层归并都遵守该规则即可保持稳定。时间复杂度和辅助空间不会因这一比较细节改变。',5,2);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (8,'软考','single','用邻接矩阵存储一个含 n 个顶点、e 条边的图，对其进行深度优先遍历的时间复杂度是？','[{"key":"A","text":"O(n²)"},{"key":"B","text":"O(n + e)"},{"key":"C","text":"O(n · e)"},{"key":"D","text":"O(e)"}]','A','邻接矩阵遍历某顶点的所有邻接点需扫描整行 n 个元素，共 n 个顶点，故为 O(n²)，与边数无关。若改用邻接表则为 O(n+e)，B 是邻接表的复杂度，不是邻接矩阵的。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (9,'软考','judge','TCP 采用三次握手建立连接，主要是为了防止已失效的连接请求报文段突然传到服务器而引发错误连接。','[]','T','正确。两次握手中服务器收到迟到的旧 SYN 就会立刻建立无效连接并浪费资源；三次握手下客户不会对旧的 SYN+ACK 作出确认，服务器收不到第三个报文便不会建立连接。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (10,'软考','single','TCP 连接中一方发送 FIN 后，该方向的数据发送能力如何变化？','[{"key":"A","text":"双方立即都不能发送"},{"key":"B","text":"发送 FIN 的一方不能再发送数据但仍可接收"},{"key":"C","text":"连接自动改用 UDP"},{"key":"D","text":"接收方必须丢弃剩余数据"}]','B','TCP 支持半关闭。一方发送 FIN 只表示自己的发送方向不再有新数据，反向字节流仍可继续，该方也能接收对端数据，直到对端发送 FIN。立即关闭双向通信会破坏四次挥手语义。',5,2);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (11,'软考','single','路由器转发 IP 数据报时，将首部 TTL 字段减 1 后发现其值为 0，正确的处理是？','[{"key":"A","text":"丢弃该数据报并向源主机发送 ICMP 超时（时间超过）报文"},{"key":"B","text":"继续向下一跳转发"},{"key":"C","text":"丢弃且不产生任何 ICMP 报文"},{"key":"D","text":"将该数据报广播到所有端口"}]','A','TTL 归零说明数据报在网络中滞留过久（可能存在路由环路），路由器必须丢弃并回送 ICMP 时间超过报文，traceroute 正是利用该机制逐跳探测路径。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (11,'软考','single','地址 172.16.5.200 使用子网掩码 255.255.255.192，其网络地址是？','[{"key":"A","text":"172.16.5.0"},{"key":"B","text":"172.16.5.128"},{"key":"C","text":"172.16.5.192"},{"key":"D","text":"172.16.5.255"}]','C','/26 子网每段包含 64 个地址，最后一字节的边界为 0、64、128、192。主机号 200 位于 192 至 255 的网段，与掩码按位与后得到网络地址 172.16.5.192。',5,2);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (12,'软考','single','主机 A 与 B 在同一以太网，A 的 ARP 缓存没有 B 的记录。A 发出的 ARP 请求帧目的 MAC 地址是？','[{"key":"A","text":"B 的单播 MAC"},{"key":"B","text":"默认网关 MAC"},{"key":"C","text":"全 1 广播地址"},{"key":"D","text":"全 0 地址"}]','C','A 尚不知道 B 的 MAC，只能把 ARP 请求封装为目的地址全 1 的广播帧，使同一广播域所有主机接收，B 再用单播应答。默认网关只在目的 IP 位于其他网段时参与。',5,2);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (13,'软考','single','TCP 的慢开始阶段中，拥塞窗口 cwnd 的变化规律是？','[{"key":"A","text":"每经过一个 RTT 就翻倍，呈指数增长"},{"key":"B","text":"每经过一个 RTT 增加 1 个 MSS，呈线性增长"},{"key":"C","text":"每收到一个确认就增加 1 个 MSS，呈线性增长"},{"key":"D","text":"始终保持不变直到超时"}]','A','慢开始每收到一个 ACK 就使 cwnd 加 1，一个 RTT 内收到的 ACK 数与 cwnd 相当，故每个 RTT 翻倍，呈指数增长；到达 ssthresh 后才改为每 RTT 加 1 的线性增长（拥塞避免）。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (14,'软考','single','在三态进程模型中，下列哪一种状态转换是不可能出现的？','[{"key":"A","text":"就绪态 → 运行态"},{"key":"B","text":"运行态 → 就绪态"},{"key":"C","text":"阻塞态 → 运行态"},{"key":"D","text":"阻塞态 → 就绪态"}]','C','阻塞进程即使所等待事件发生，也必须先被唤醒进入就绪队列重新参与调度，由调度程序选中后才能获得 CPU，因此不存在阻塞态直接跳到运行态的转换。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (14,'软考','single','进程因等待磁盘读操作完成，即使处理机空闲也不能执行，此时处于什么状态？','[{"key":"A","text":"运行态"},{"key":"B","text":"就绪态"},{"key":"C","text":"阻塞态"},{"key":"D","text":"终止态"}]','C','进程等待尚未完成的外部事件，属于阻塞态。就绪态只缺少处理机，一旦被调度便可运行，而该进程即使立即获得处理机也无法继续，所以不能判为就绪态或运行态。',5,1);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (15,'软考','single','时间片轮转（RR）调度算法中，若时间片设置得非常大，该算法将退化成？','[{"key":"A","text":"先来先服务（FCFS）"},{"key":"B","text":"短作业优先（SJF）"},{"key":"C","text":"高响应比优先（HRRN）"},{"key":"D","text":"多级反馈队列"}]','A','时间片大到每个进程都能在自己的第一个时间片内运行完毕，就不会发生抢占与轮转，等价于按到达顺序依次执行，即 FCFS。反之时间片过小则上下文切换开销剧增。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (16,'软考','single','下列页面置换算法中，可能出现 Belady 异常（分配的物理块数增加，缺页次数反而增加）的是？','[{"key":"A","text":"FIFO"},{"key":"B","text":"LRU"},{"key":"C","text":"OPT"},{"key":"D","text":"Clock（时钟）算法"}]','A','FIFO 只看装入时间，不具备栈特性，增加物理块可能反而淘汰掉即将访问的页面，从而出现 Belady 异常。LRU 与 OPT 均满足栈特性，物理块增加时缺页次数单调不增。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (16,'软考','judge','最佳置换算法 OPT 淘汰以后永不使用或最长时间内不再被访问的页面，其缺页次数最少，但因无法预知未来而不能实际实现。','[]','T','正确。OPT 需要事先知道完整的页面访问序列，实际系统无法做到，故仅作为理论下界，用来评价 LRU、FIFO 等实际算法的优劣（比较缺页率与 OPT 的差距）。',5,2);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (17,'软考','single','死锁产生的四个必要条件中，不包括下列哪一项？','[{"key":"A","text":"互斥条件"},{"key":"B","text":"请求与保持条件"},{"key":"C","text":"不可抢占条件"},{"key":"D","text":"优先级抢占条件"}]','D','死锁四条件为：资源互斥使用、占有资源的同时又申请新资源（请求与保持）、资源不可被强行剥夺、存在进程—资源的循环等待链。优先级抢占是与解除死锁相关的调度概念，并非产生死锁的条件。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (18,'软考','single','一条 4 段流水线（各段时间相等）连续执行 100 条指令，不发生任何冲突与气泡时，相对于非流水线执行的加速比约为？','[{"key":"A","text":"4"},{"key":"B","text":"3.88"},{"key":"C","text":"100"},{"key":"D","text":"25"}]','B','非流水线需 100×4 = 400 个周期，流水线需 4 + (100-1) = 103 个周期，加速比 = 400/103 ≈ 3.88。指令数趋于无穷时加速比才趋近段数 4，故 A 是理论上限而非本题答案。',5,4);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (19,'软考','single','用若干片容量为 512K×8 位的 DRAM 芯片构成 2M×8 位的存储器，需要的芯片数是？','[{"key":"A","text":"4 片"},{"key":"B","text":"8 片"},{"key":"C","text":"2 片"},{"key":"D","text":"16 片"}]','A','目标与单片位宽同为 8 位，只需字扩展：2M / 512K = 4，故用 4 片，片选信号由高位地址译码产生。若位宽也需扩展（如构成 2M×32 位），芯片数才要再乘以位扩展倍数。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (19,'软考','judge','存储系统采用 Cache—主存—辅存层次结构，目的是在成本可接受的条件下使平均访问速度接近最快层、容量接近最大层。','[]','T','正确。层次的依据是程序访问的局部性原理（时间局部性与空间局部性），用少量高速器件覆盖大部分访问，从而以较低成本换取接近 Cache 的速度与主存/辅存的容量。',5,2);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (20,'软考','single','补码加减法运算中，判断溢出（OF）常用的方法是？','[{"key":"A","text":"最高位（符号位）进位与次高位进位相异或"},{"key":"B","text":"最高位有进位就溢出"},{"key":"C","text":"运算结果为负数就溢出"},{"key":"D","text":"看进位标志 CF 是否为 1"}]','A','只有符号位进位 Cn 与最高数值位进位 Cn-1 不同（即 Cn ⊕ Cn-1 = 1）时才表示补码溢出。B、D 把 CF 当成溢出标志——CF 用于无符号数；C 中结果为负完全可能是正确结果。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (21,'软考','single','CPU 中程序计数器（PC）的作用是？','[{"key":"A","text":"存放下一条将要执行的指令的地址"},{"key":"B","text":"存放当前指令的操作码"},{"key":"C","text":"存放算术逻辑运算的结果"},{"key":"D","text":"存放栈顶元素的地址"}]','A','PC 指向待取指令的地址，取指后自动加增量或由转移指令改写。B 是指令寄存器 IR 的职责，C 属于通用寄存器或累加器，D 是堆栈指针 SP 的功能。',5,2);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (21,'软考','judge','指令寄存器 IR 用于存放当前正在执行的指令，其内容通常由存储器数据寄存器 MDR 经内部总线送入。','[]','T','正确。取指周期中把 MDR 中的指令字经 CPU 内部总线打入 IR，之后由指令译码器对 IR 中的操作码译码并产生控制信号，IR 的内容在本条指令执行期间保持不变。',5,2);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (31,'软考','single','命题公式 p → q 与下列哪个公式逻辑等价？','[{"key":"A","text":"¬p ∨ q"},{"key":"B","text":"p ∨ ¬q"},{"key":"C","text":"q → p"},{"key":"D","text":"p ∧ ¬q"}]','A','列出真值表：p → q 仅在 p 真 q 假时为假，其余三种情况为真，与 ¬p ∨ q 完全一致。C 是其逆命题，与 p → q 不等价（只有逆否命题 ¬q → ¬p 才等价）；D 恰为其否定。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (31,'软考','single','命题公式 ¬(p ∧ q) 与下列哪个公式等价？','[{"key":"A","text":"¬p ∨ ¬q"},{"key":"B","text":"¬p ∧ ¬q"},{"key":"C","text":"p ∨ q"},{"key":"D","text":"p → q"}]','A','由德摩根定律，否定合取得各支否定之析取：¬(p ∧ q) ≡ ¬p ∨ ¬q。B 是 ¬(p ∨ q) 的等价式，两者容易混淆；C 与原式在 p、q 一真一假时的取值恰好相反。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (31,'软考','judge','若蕴涵式 p → q 为真且前件 p 为真，则可推出 q 必为真（假言推理 Modus Ponens）。','[]','T','正确。这是最基本的有效推理规则：真值表中 p → q 为真且 p 为真时，只有 q 为真这一行满足条件。注意不能反推：q 为真时不能断言 p 为真（肯定后件是谬误）。',5,2);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (31,'软考','single','命题 p→q 在哪一种真值组合下为假？','[{"key":"A","text":"p 真且 q 真"},{"key":"B","text":"p 真且 q 假"},{"key":"C","text":"p 假且 q 真"},{"key":"D","text":"p 假且 q 假"}]','B','蕴含式 p→q 等价于 非p 或 q，只有前件 p 为真而后件 q 为假时，两部分同时为假，整个命题才为假。当前件为假时蕴含恒真，这是本题最常见的干扰点。',5,2);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (31,'NCRE','single','已知命题 p 为真、q 为假，则表达式 (p∧q)∨非q 的真值是？','[{"key":"A","text":"真"},{"key":"B","text":"假"},{"key":"C","text":"无法确定"},{"key":"D","text":"与 p 无关且必假"}]','A','p∧q 因 q 为假而为假，非q 为真，两者析取结果为真。题目已经给出 p、q 的全部真值，所以不能选无法确定，选项 D 虽提到与 p 无关，却把最终真值判断反了。',5,2);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (32,'软考','single','含 n 个顶点的连通带权无向图，其最小生成树所包含的边数是？','[{"key":"A","text":"n - 1"},{"key":"B","text":"n"},{"key":"C","text":"n + 1"},{"key":"D","text":"边数不固定，由权值分布决定"}]','A','生成树是包含全部顶点的极小连通子图，树中边数恒为顶点数减一（n-1），与权值分布无关。权值只决定选哪 n-1 条边，不决定边的条数。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (32,'软考','single','一个连通无向图有 7 个顶点，它的任意一棵生成树包含多少条边？','[{"key":"A","text":"6"},{"key":"B","text":"7"},{"key":"C","text":"8"},{"key":"D","text":"由边权决定"}]','A','含 n 个顶点的树恒有 n-1 条边，所以 7 个顶点的生成树一定有 6 条边。边权只决定哪棵生成树总代价最小，不改变树的边数，多一条边将形成环，少一条则无法连通。',5,1);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (33,'软考','judge','采用拉链法（链地址法）处理冲突时，哈希表的装填因子 α 可以大于 1。','[]','T','正确。拉链法中所有同义词都挂在同一桶的链表上，不会抢占其他地址，记录数 n 可以超过表长 m，即 α = n/m > 1。而开放地址法必须保证 α < 1。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (33,'软考','single','编译器符号表采用哈希结构，装填因子由 0.4 增至 0.9 时通常会出现什么变化？','[{"key":"A","text":"冲突减少且查找更快"},{"key":"B","text":"冲突增多且平均查找长度增加"},{"key":"C","text":"散列函数自动有序"},{"key":"D","text":"复杂度固定为 O(log n)"}]','B','装填因子越接近 1，空槽越少，冲突和连续探测的概率通常越高，平均查找长度随之增加。散列函数不会自动排序，工程上常通过扩容和重新散列降低装填因子。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (34,'软考','single','在直接映射 Cache 中，若两个被频繁交替访问的主存块恰好映射到同一行，会产生什么现象？','[{"key":"A","text":"冲突缺失（抖动），命中率大幅下降"},{"key":"B","text":"容量缺失，需增大 Cache 容量才能解决"},{"key":"C","text":"强制缺失，属首次访问的必然开销"},{"key":"D","text":"Cache 会自动调整映射规则以避免冲突"}]','A','直接映射下两块的组号相同却不能共存，每次访问都会被对方替换掉，形成冲突缺失（抖动）。这与 Cache 总容量无关，增大容量无效；提高相联度或改变程序访问模式才能缓解。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (34,'软考','single','二路组相联 Cache 的某组已有两个有效块，访问映射到该组的新块且两个标记均不匹配，应如何处理？','[{"key":"A","text":"在该组内按替换策略淘汰一块"},{"key":"B","text":"放入任意其他组"},{"key":"C","text":"修改主存地址"},{"key":"D","text":"清空整个 Cache"}]','A','组相联先由地址索引唯一确定组，主存块只能放在该组的任一行。组内两行均有效且未命中时，要按 LRU、FIFO 等策略选择一行替换，不能越组存放或修改地址。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (1,'NCRE','single','在单链表中，已知结点 *p，要在 *p 之后插入新结点 *s，正确的操作序列是？','[{"key":"A","text":"s->next = p->next； p->next = s；"},{"key":"B","text":"p->next = s； s->next = p->next；"},{"key":"C","text":"s->next = p； p->next = s；"},{"key":"D","text":"p->next = s->next； s->next = p；"}]','A','后插必须先让新结点 s 接上 p 原来的后继，再把 p 的 next 指向 s。若顺序颠倒（B），s->next 会指向 s 自身造成断链；C 让 s 指回 p 形成环；D 破坏了 p 的原后继。',5,2);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (1,'NCRE','single','C 语言数组 a 有 8 个元素，删除下标为 2 的元素并保持其余元素次序，至少要前移多少个元素？','[{"key":"A","text":"2"},{"key":"B","text":"5"},{"key":"C","text":"6"},{"key":"D","text":"8"}]','B','删除 a[2] 后，原下标 3 至 7 的五个元素都要依次前移一位，才能保持连续存储和相对次序，因此移动 8-2-1=5 个。下标从 0 开始是关键，C 把待删元素本身也计入移动。',5,2);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (2,'NCRE','judge','栈是一种先进先出（FIFO）的线性表。','[]','F','错误。栈是后进先出（LIFO）的线性表，插入和删除都只在栈顶进行；先进先出描述的是队列。栈的典型应用包括函数调用、表达式求值、括号匹配与递归转非递归。',5,1);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (2,'NCRE','single','递归函数计算 factorial(4) 时，尚未返回的各层调用信息最适合由哪种结构管理？','[{"key":"A","text":"栈"},{"key":"B","text":"队列"},{"key":"C","text":"哈希集合"},{"key":"D","text":"循环链表"}]','A','递归调用遵循后调用者先返回的次序，每次调用的参数、局部变量和返回地址构成栈帧压入调用栈，返回时逆序弹出。队列的先进先出不符合递归展开与回退过程。',5,1);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (3,'NCRE','single','Python 程序需要频繁从左端删除并从右端加入元素，最适合使用 collections 中的哪种结构？','[{"key":"A","text":"deque"},{"key":"B","text":"Counter"},{"key":"C","text":"namedtuple"},{"key":"D","text":"ChainMap"}]','A','deque 是双端队列，左右两端追加和弹出通常都是 O(1)，适合维护先进先出数据。普通列表左端删除需要整体移动元素，Counter 用于计数，其他选项也不提供高效队列操作。',5,1);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (3,'NCRE','single','Python 程序需要频繁从序列左端删除并从右端加入元素，最适合使用 collections 中的哪种结构？','[{"key":"A","text":"deque"},{"key":"B","text":"Counter"},{"key":"C","text":"namedtuple"},{"key":"D","text":"ChainMap"}]','A','deque 是双端队列，左右两端追加和弹出通常都是 O(1)，适合先进先出数据。普通列表从左端删除需要移动后续元素，Counter 用于计数，namedtuple 和 ChainMap 也不提供高效队列操作。',5,1);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (4,'NCRE','single','递归函数按左子树、右子树、根结点的顺序输出二叉树，采用的是哪种遍历？','[{"key":"A","text":"先序"},{"key":"B","text":"中序"},{"key":"C","text":"后序"},{"key":"D","text":"层序"}]','C','后序遍历的固定次序就是左子树、右子树、根结点，递归代码会在两次子树调用后输出当前结点。先序先访问根，中序在两棵子树之间访问根，层序则借助队列逐层处理。',5,1);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (5,'NCRE','judge','B+ 树的叶子结点通过指针连接成一个有序链表，因此特别适合进行范围查询和顺序扫描。','[]','T','正确。叶子链表使范围查询只需定位到起始关键字再沿链表顺序读取，避免了 B 树那样的中序回溯。这也是绝大多数数据库索引采用 B+ 树而非 B 树的原因。',5,2);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (6,'NCRE','single','快速排序对列表 [3,1,4,2] 选择 3 为枢轴，一趟划分后枢轴左侧应包含哪些元素？','[{"key":"A","text":"1、2"},{"key":"B","text":"4"},{"key":"C","text":"1、4"},{"key":"D","text":"2、4"}]','A','一趟划分按与枢轴 3 的大小关系分区，小于 3 的 1、2 应位于左侧，大于 3 的 4 位于右侧，左右侧内部次序可随实现变化。其余选项都把大于枢轴的 4 放错区域。',5,2);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (7,'NCRE','judge','二路归并排序每趟把若干个长度为 L 的有序段两两归并成长度为 2L 的有序段，且在归并时相等关键字可保持原有次序，因此它是稳定排序。','[]','T','正确。归并比较两个有序段时遇到相等关键字先取左段元素，故稳定性得以保持；每趟有序段长度翻倍，共需 ⌈log₂ n⌉ 趟。',5,2);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (8,'NCRE','single','用邻接表表示社交网络，从用户 s 开始按距离逐层寻找一跳、二跳和三跳用户，应采用？','[{"key":"A","text":"广度优先搜索"},{"key":"B","text":"深度优先搜索"},{"key":"C","text":"快速排序"},{"key":"D","text":"二分查找"}]','A','广度优先搜索借助队列先访问起点的一跳邻居，再访问二跳和三跳邻居，天然按无权图最短距离分层。深度优先会沿一条路径深入，不能保证首次访问顺序按距离递增。',5,1);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (8,'NCRE','single','用邻接表表示社交网络，从用户 s 开始按距离逐层寻找一跳、二跳和三跳用户，应采用？','[{"key":"A","text":"广度优先搜索"},{"key":"B","text":"深度优先搜索"},{"key":"C","text":"快速排序"},{"key":"D","text":"二分查找"}]','A','广度优先搜索借助队列先访问起点的一跳邻居，再访问二跳和三跳邻居，天然按无权图最短距离分层。深度优先会沿一条路径深入，不能保证首次访问顺序按距离递增。',5,1);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (9,'NCRE','single','TCP 三次握手过程中，第二个报文段（服务器发给客户）中标志位 SYN 与 ACK 的取值分别是？','[{"key":"A","text":"SYN = 1，ACK = 1"},{"key":"B","text":"SYN = 1，ACK = 0"},{"key":"C","text":"SYN = 0，ACK = 1"},{"key":"D","text":"SYN = 0，ACK = 0"}]','A','该报文既要应答客户的连接请求（ACK = 1，ack = x+1），又要发起自己的连接请求（SYN = 1，seq = y），故称为 SYN+ACK 报文。第一个报文 SYN=1、ACK=0，第三个 SYN=0、ACK=1。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (9,'NCRE','single','客户端调用 TCP connect 主动建立连接时，首先发送的报文段通常设置哪个控制位？','[{"key":"A","text":"SYN"},{"key":"B","text":"FIN"},{"key":"C","text":"RST"},{"key":"D","text":"URG"}]','A','主动建立 TCP 连接时客户端先发送 SYN 并给出初始序号，服务器回复 SYN+ACK，客户端再确认。FIN 用于有序释放连接，RST 用于异常复位，URG 则表示存在紧急数据。',5,1);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (9,'NCRE','single','客户端调用 TCP connect 主动建立连接时，首先发送的报文段通常设置哪个控制位？','[{"key":"A","text":"SYN"},{"key":"B","text":"FIN"},{"key":"C","text":"RST"},{"key":"D","text":"URG"}]','A','主动建立 TCP 连接时客户端先发送 SYN 并给出初始序号，服务器回复 SYN+ACK，客户端再确认。FIN 用于有序释放连接，RST 用于异常复位，URG 表示报文含有紧急数据。',5,1);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (10,'NCRE','judge','TCP 连接释放时，主动关闭方在发出最后一个 ACK 后进入 TIME_WAIT 状态并等待 2MSL。','[]','T','正确。等待 2MSL 有两个作用：保证最后一个 ACK 能到达对方（丢失时对方会重发 FIN），以及让本次连接残留的报文段在网络中消散，避免干扰后续新建的相同四元组连接。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (10,'NCRE','single','TCP 是全双工协议，一个方向发送 FIN 后，另一方向是否还能继续发送尚未完成的数据？','[{"key":"A","text":"可以，连接可处于半关闭状态"},{"key":"B","text":"不可以，双方立即断开"},{"key":"C","text":"只能发送 UDP 数据"},{"key":"D","text":"仅能发送广播数据"}]','A','TCP 的两个方向可以分别关闭，发送 FIN 仅表示本方不再发送新数据，并不自动终止反向字节流。对端仍可发送剩余数据，之后再发送自己的 FIN，这也是通常需要四次挥手的原因。',5,2);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (11,'NCRE','single','IPv4 地址 192.168.1.70 使用 /27 前缀，其所在子网的网络地址是？','[{"key":"A","text":"192.168.1.32"},{"key":"B","text":"192.168.1.64"},{"key":"C","text":"192.168.1.70"},{"key":"D","text":"192.168.1.96"}]','B','/27 对应每个子网 32 个地址，最后一字节的边界为 0、32、64、96 等。70 位于 64 至 95 的范围内，所以网络地址为 192.168.1.64，96 已属于下一子网。',5,2);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (11,'NCRE','single','IPv4 地址 192.168.1.70 使用 /27 前缀，其所在子网的网络地址是？','[{"key":"A","text":"192.168.1.32"},{"key":"B","text":"192.168.1.64"},{"key":"C","text":"192.168.1.70"},{"key":"D","text":"192.168.1.96"}]','B','/27 对应每个子网 32 个地址，最后一字节的边界为 0、32、64、96 等。70 位于 64 至 95 的范围内，所以网络地址为 192.168.1.64，96 已属于下一子网。',5,2);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (12,'NCRE','single','ARP 协议的主要功能是？','[{"key":"A","text":"由 IP 地址解析出对应的 MAC 地址"},{"key":"B","text":"由 MAC 地址解析出对应的 IP 地址"},{"key":"C","text":"由域名解析出对应的 IP 地址"},{"key":"D","text":"由 IP 地址解析出对应的端口号"}]','A','ARP 解决同一链路上的地址映射问题：已知下一跳 IP，查得其 MAC 才能封装成帧。B 是 RARP 的功能，C 属于 DNS，D 由传输层首部直接携带，无需解析。',5,2);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (12,'NCRE','single','主机已知同一局域网设备的 IPv4 地址但不知道其 MAC 地址，应首先使用哪个协议？','[{"key":"A","text":"ARP"},{"key":"B","text":"DNS"},{"key":"C","text":"HTTP"},{"key":"D","text":"SMTP"}]','A','ARP 用于把同一链路中的 IPv4 地址解析为 MAC 地址，得到结果后才能填写以太网目的地址。DNS 解析域名，HTTP 和 SMTP 分别传输网页与邮件，都不能完成本地二层地址查询。',5,1);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (12,'NCRE','single','主机已知同一局域网设备的 IPv4 地址但不知道其 MAC 地址，应首先使用哪个协议？','[{"key":"A","text":"ARP"},{"key":"B","text":"DNS"},{"key":"C","text":"HTTP"},{"key":"D","text":"SMTP"}]','A','ARP 用于把同一链路中的 IPv4 地址解析为 MAC 地址，得到结果后才能填写以太网目的地址。DNS 解析域名，HTTP 和 SMTP 分别传输网页与邮件，都不能完成本地二层地址查询。',5,1);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (13,'NCRE','judge','发送方的实际发送窗口上限取拥塞窗口 cwnd 与接收窗口 rwnd 中的较小者。','[]','T','正确。cwnd 反映网络承载能力，rwnd 反映接收方缓存能力，两者分别约束发送量，因此发送窗口 = min(cwnd, rwnd)，同时满足流量控制与拥塞控制的要求。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (13,'NCRE','single','网络出现拥塞并检测到丢包时，TCP 发送方通常应如何调整发送速率？','[{"key":"A","text":"减小拥塞窗口"},{"key":"B","text":"无限增大发送窗口"},{"key":"C","text":"关闭所有确认"},{"key":"D","text":"改用广播发送"}]','A','丢包通常表示网络承载接近上限，TCP 会通过乘性减小等机制缩小拥塞窗口，降低在途数据量。继续增大发送只会加重拥塞，关闭确认会破坏可靠传输，广播也不是 TCP 的发送方式。',5,1);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (14,'NCRE','single','操作系统把一个时间片用完的运行进程移回就绪队列，该进程发生的状态转换是？','[{"key":"A","text":"运行态到就绪态"},{"key":"B","text":"阻塞态到运行态"},{"key":"C","text":"就绪态到阻塞态"},{"key":"D","text":"终止态到就绪态"}]','A','时间片耗尽表示进程仍具备运行条件，只是处理机被调度器收回，因此从运行态转为就绪态并等待再次调度。它没有等待外部事件，所以不会进入阻塞态，终止态也不能恢复。',5,1);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (15,'NCRE','judge','高响应比优先调度算法的响应比 =（等待时间 + 要求服务时间）/ 要求服务时间，它既照顾了短作业，又不会使长作业长期得不到服务。','[]','T','正确。短作业因分母小响应比上升快而优先；长作业等待时间不断增大，响应比也会随之提高，从而在若干轮后获得 CPU，克服了 SJF 中长作业"饿死"的缺点。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (16,'NCRE','single','页面置换中，淘汰进入内存时间最早页面的算法是？','[{"key":"A","text":"FIFO"},{"key":"B","text":"LRU"},{"key":"C","text":"OPT"},{"key":"D","text":"二分查找"}]','A','FIFO 按页面进入内存的先后维护队列，缺页且无空闲页框时淘汰队头，也就是驻留时间最久的页面。LRU 淘汰最近最久未访问者，OPT 根据未来访问，二分查找不是置换算法。',5,1);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (17,'NCRE','judge','在资源分配图中只要出现环路，系统就一定处于死锁状态。','[]','F','错误。若环中每类资源只有一个实例，则环路是死锁的充分必要条件；若某类资源有多个实例，环只是死锁的必要条件——环外进程释放资源后环内进程仍可能推进，故不一定死锁。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (18,'NCRE','judge','流水线中的结构冲突是指多条指令在同一时钟周期内争用同一个功能部件（如同时访存）。','[]','T','正确。结构冲突源于硬件资源不足，解决办法是增加部件（如指令/数据分离的 Cache）或插入气泡；它与数据冲突（依赖）、控制冲突（转移）并列为流水线三大冲突。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (20,'NCRE','judge','在补码加减运算中，符号位与数值位一起参与运算，符号位产生的进位自然丢弃。','[]','T','正确。这正是补码的优点：加减法可统一用加法器完成，符号位无需单独处理，最高位的进位直接舍去（它对应模 2^n 运算），结果即为正确的补码。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (31,'NCRE','single','Python 布尔表达式 not True or False 的值是？','[{"key":"A","text":"True"},{"key":"B","text":"False"},{"key":"C","text":"None"},{"key":"D","text":"语法错误"}]','B','not 的优先级高于 or，先计算 not True 得 False，再计算 False or False，结果仍为 False。表达式语法合法且结果是布尔值，不会得到 None，选择 True 则忽略了取反。',5,1);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (32,'NCRE','judge','Kruskal 算法按边权值从小到大的顺序考察每条边，只要该边与已选边不构成回路就把它加入，最终得到最小生成树。','[]','T','正确。该贪心策略每次选择能连接两个不同连通分量的最小权边，用并查集判断是否成环，时间复杂度主要取决于边的排序 O(e log e)，适合稀疏图。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (33,'NCRE','single','Python 字典在哈希冲突较少且装填因子受控时，按键读取值的平均时间复杂度通常为？','[{"key":"A","text":"O(1)"},{"key":"B","text":"O(log n)"},{"key":"C","text":"O(n)"},{"key":"D","text":"O(n²)"}]','A','字典通过键的哈希值直接定位槽位，在冲突较少且装填因子受控时，平均只需常数次探测，因此读取为 O(1)。极端冲突下可能变慢，但不能据此改变通常情况下的复杂度。',5,1);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (34,'NCRE','judge','写回法（Write Back）需要在每个 Cache 行中设置脏位（dirty bit），换出时只有脏位为 1 的行才需要写回主存。','[]','T','正确。写回法仅在 Cache 中修改并用脏位标记，替换时才一次性写回，减少了访存次数，但存在一致性问题；写直达法则每次都写主存，无需脏位但速度较慢。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (22,'基础','single','极限 lim(x→0) [ sin(3x) / tan(2x) ] 的值是？','[{"key":"A","text":"3/2"},{"key":"B","text":"2/3"},{"key":"C","text":"1"},{"key":"D","text":"0"}]','A','x→0 时 sin(3x) ~ 3x、tan(2x) ~ 2x，等价无穷小替换得极限 = 3x / 2x = 3/2。也可用洛必达法则：分子导数 3cos3x、分母导数 2sec²2x，代入 x = 0 得 3/2。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (22,'基础','judge','若 lim(x→x₀) f(x) 存在，则函数 f(x) 在 x₀ 处一定有定义。','[]','F','错误。极限只关心 x₀ 附近（去心邻域）的函数值，与 f 在 x₀ 处是否有定义、取何值无关。例如 sin x / x 在 x = 0 处无定义，但 x→0 时极限为 1（可去间断点）。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (23,'基础','single','设 f(x) = x² · e^x，则 f''(x) 等于？','[{"key":"A","text":"e^x (x² + 2x)"},{"key":"B","text":"2x e^x"},{"key":"C","text":"e^x (x² + x)"},{"key":"D","text":"x² e^x"}]','A','由乘积求导法则：f''(x) = (x²)'' e^x + x² (e^x)'' = 2x e^x + x² e^x = e^x (x² + 2x)。B 只对 x² 求导而漏掉 e^x 项，C 系数错误，D 漏掉了 2x e^x 项。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (23,'基础','judge','若函数 f(x) 在 x₀ 处可导，则 f(x) 在 x₀ 处必定连续；反之，连续不一定可导。','[]','T','正确。可导蕴含连续：f(x) - f(x₀) = f''(x₀)(x - x₀) + o(x - x₀) 随 x→x₀ 趋于 0。反之不成立，如 y = |x| 在 x = 0 处连续但左右导数不相等，不可导。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (24,'基础','single','定积分 ∫(0→1) x · e^x dx 的值是？','[{"key":"A","text":"1"},{"key":"B","text":"e"},{"key":"C","text":"e - 1"},{"key":"D","text":"0"}]','A','分部积分得 ∫x e^x dx=(x-1)e^x+C，在 0 到 1 上代入端点，结果为 0-(-1)=1。把答案写成 e-1 是漏掉因子 x 后计算 ∫e^x dx 的结果。',5,4);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (24,'基础','judge','定积分的几何意义是曲边梯形面积的代数和，位于 x 轴下方的部分取负值。','[]','T','正确。定积分是有符号量：x 轴上方取正、下方取负，上下抵消。因此求平面图形总面积时需对被积函数取绝对值或分段积分，不能直接照搬定积分值。',5,2);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (25,'基础','single','矩阵 A = [[1, 2], [2, 4]] 的秩 r(A) 是？','[{"key":"A","text":"1"},{"key":"B","text":"2"},{"key":"C","text":"0"},{"key":"D","text":"3"}]','A','二阶行列式 det(A) = 1×4 - 2×2 = 0，故秩小于 2；又 A 不是零矩阵，至少有一个非零一阶子式，故 r(A) = 1。第二行是第一行的 2 倍，两行线性相关。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (25,'基础','judge','若 A 为 m×n 矩阵，则 r(A) ≤ min(m, n)，且对任意可乘矩阵 B 有 r(AB) ≤ min(r(A), r(B))。','[]','T','正确。秩不超过行数与列数，且矩阵相乘不增秩：AB 的行向量是 A 的行向量的线性组合、列向量是 B 的列向量的线性组合，故秩不会超过任一因子。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (26,'基础','single','矩阵 A = [[4, 1], [2, 3]] 的两个特征值是？','[{"key":"A","text":"5 与 2"},{"key":"B","text":"7 与 0"},{"key":"C","text":"1 与 10"},{"key":"D","text":"4 与 3"}]','A','特征方程 |λI - A| = (λ-4)(λ-3) - 2 = λ² - 7λ + 10 = 0，解得 λ = 5 与 2。校验：tr(A) = 7 = 5 + 2，det(A) = 10 = 5 × 2，均吻合，可用来快速验算。',5,4);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (26,'基础','judge','矩阵中属于不同特征值的特征向量必定线性无关。','[]','T','正确。可用反证法与数学归纳法证明：若不同特征值的特征向量线性相关，取最短的相关组可导出矛盾。同一特征值的多个特征向量组成的特征子空间内，则可能因重数不足而不存在足够多的无关向量。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (27,'基础','single','设随机变量 X ~ B(10, 0.3)，则 X 的数学期望 E(X) 与方差 D(X) 分别是？','[{"key":"A","text":"3 与 2.1"},{"key":"B","text":"3 与 3"},{"key":"C","text":"0.3 与 2.1"},{"key":"D","text":"3 与 0.21"}]','A','二项分布的期望 E(X) = np = 10 × 0.3 = 3，方差 D(X) = np(1-p) = 10 × 0.3 × 0.7 = 2.1。B 错把方差当成 np，C 把单次成功概率误当成期望，D 小数点点错。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (27,'基础','judge','若随机变量 X 服从参数为 λ 的泊松分布 P(λ)，则 E(X) = D(X) = λ。','[]','T','正确。由泊松分布的定义可直接求和得到 E(X) = λ，再由 E(X²) = λ² + λ 得 D(X) = E(X²) - [E(X)]² = λ。期望等于方差是泊松分布区别于二项分布的显著特征。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (28,'基础','single','设 X₁, X₂, …, X_n 独立同分布，E(X_i) = μ，D(X_i) = σ² > 0。当 n 充分大时，样本均值 X̄ 近似服从的分布是？','[{"key":"A","text":"N(μ, σ²/n)"},{"key":"B","text":"N(μ, σ²)"},{"key":"C","text":"N(0, 1)"},{"key":"D","text":"参数为 nμ 的泊松分布"}]','A','由独立同分布情形的中心极限定理，(X̄ - μ)/(σ/√n) 依分布收敛于 N(0,1)，故 X̄ 近似服从 N(μ, σ²/n)。注意方差随 n 增大而缩小为 σ²/n，B 忽略了样本量对精度的改善。',5,4);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (28,'基础','judge','中心极限定理表明：无论总体服从什么分布，只要期望与方差存在，样本均值的标准化形式在 n 充分大时都近似服从标准正态分布。','[]','T','正确。这正是中心极限定理的核心——对总体分布形式几乎不作要求（只需独立同分布且方差有限），正态性来自"求和"这一操作本身，因此它是统计推断中大样本方法的理论基石。',5,3);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (29,'基础','single','以初速度 v₀ 与水平方向成 θ 角斜抛物体（不计空气阻力，落回同一水平面），其水平射程为？','[{"key":"A","text":"v₀² sin(2θ) / g"},{"key":"B","text":"v₀² sin θ / g"},{"key":"C","text":"2 v₀ sin θ / g"},{"key":"D","text":"v₀² / g"}]','A','飞行时间为 2v₀sinθ/g，水平方向速度保持 v₀cosθ，相乘得到射程 v₀²sin(2θ)/g。遗漏二倍角关系或把竖直分速度直接当作飞行时间都会得到错误表达式。',5,2);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (29,'基础','judge','斜抛运动中，物体运动到轨迹最高点时的速度为零。','[]','F','错误。最高点处竖直分速度为零，但水平分速度始终保持 v₀ cos θ 不变（忽略空气阻力时水平方向不受力），故合速度不为零，方向沿水平。若速度为零物体就会竖直下落。',5,2);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (30,'基础','single','弹簧振子（劲度系数 k、质量 m）做简谐振动，其周期 T 与振幅 A 的关系是？','[{"key":"A","text":"与振幅无关，T = 2π√(m/k)"},{"key":"B","text":"T 与振幅 A 成正比"},{"key":"C","text":"T 与 A² 成正比"},{"key":"D","text":"T 与 A 成反比"}]','A','简谐振动的周期由系统本身性质决定：T = 2π√(m/k)，与振幅无关，这一性质称为等时性。振幅只影响最大速度与能量（E ∝ A²），不影响周期。',5,2);
INSERT INTO question (knowledge_id, source, type, title, options, answer, analysis, score, difficulty) VALUES (30,'基础','judge','简谐振动中，物体通过平衡位置时速度达到最大，而加速度为零。','[]','T','正确。平衡位置处位移 x = 0，回复力 F = -kx = 0 故加速度为 0；此时势能全部转化为动能，速率最大。在最大位移处恰好相反：速度为零、加速度最大。',5,2);
